<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>내 계좌</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #e0f2fe; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="t">🏦 내 계좌</h2>
  <h1 id="bal"></h1>
  <input id="amt" type="number" placeholder="금액">
  <div id="bx" class="box row">
    <button id="dep">입금</button>
    <button id="wd">출금</button>
  </div>
  <p id="msg"></p>
  <script>
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }

    var balance;

    // 이 함수를 설명하세요...
    function show() {
      document.getElementById("bal").textContent = String(balance) + '원';
      __save('balance', balance);
      document.getElementById("amt").value = '';
    }

    document.getElementById("dep").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("amt").value) || 0) > 0) {
        balance = (typeof balance === 'number' ? balance : 0) + (parseFloat(document.getElementById("amt").value) || 0);
        document.getElementById("msg").textContent = '입금했어요';
        show();
      } else {
        document.getElementById("msg").textContent = '0보다 큰 금액을 넣어 주세요';
      }
    });
    document.getElementById("wd").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("amt").value) || 0) <= 0) {
        document.getElementById("msg").textContent = '0보다 큰 금액을 넣어 주세요';
      } else if ((parseFloat(document.getElementById("amt").value) || 0) > balance) {
        document.getElementById("msg").textContent = '잔액이 모자라요!';
      } else {
        balance = (typeof balance === 'number' ? balance : 0) + (parseFloat(document.getElementById("amt").value) || 0) * -1;
        document.getElementById("msg").textContent = '출금했어요';
        show();
      }
    });

    balance = __load('balance', 10000);
    show();
  </script>
</body>
</html>
```

