<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>반응 속도</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h2 id="신호">기다리세요…</h2>
  <button id="버튼1">누르기</button>
  <p id="안내">초록색이 되면 바로 눌러요. 다시 하려면 위의 실행하기를 다시 눌러요</p>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var 상태, 밀리초;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    __timers.push(setInterval(function () {
      if (상태 == 1) {
        밀리초 = (typeof 밀리초 === 'number' ? 밀리초 : 0) + 10;
      }
    }, 20));
    document.getElementById("버튼1").addEventListener('click', function () {
      if (상태 == 0) {
        document.getElementById("신호").textContent = '너무 일러요! 초록색을 기다려요';
        상태 = 2;
      }
      if (상태 == 1) {
        상태 = 2;
        document.getElementById("신호").textContent = ['반응 속도: ',밀리초,' 밀리초'].join('');
        __beep(261.63, 0.1);
      }
    });

    상태 = 0;
    밀리초 = 0;
    document.getElementById("신호").textContent = '기다리세요…';
    document.getElementById("신호").style.background = "#ef4444";
    setTimeout(function () {
      상태 = 1;
      밀리초 = 0;
      document.getElementById("신호").textContent = '지금 눌러요!';
      document.getElementById("신호").style.background = "#22c55e";
    }, (mathRandomInt(2, 5)) * 1000);
  </script>
</body>
</html>
```

```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Catch the Dot</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
    canvas { max-width: 100%; background: #ffffff; border: 1px solid #d1d5db; border-radius: 8px; touch-action: manipulation; }
  </style>
</head>
<body>
  <h1 id="title">Catch the Dot</h1>
  <h2 id="score">Score: 0</h2>
  <canvas id="board" width="320" height="240"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var x, pts, y;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function drawDot() {
      x = mathRandomInt(20, 300);
      y = mathRandomInt(20, 220);
      __clear("board");
      __circle("board", x, y, 18, "#ef4444");
    }

    document.getElementById("board").addEventListener('click', function (e) {
      __pos(e, this);
      if (Math.abs(__mx - x) < 22 && Math.abs(__my - y) < 22) {
        pts = (typeof pts === 'number' ? pts : 0) + 1;
        document.getElementById("score").textContent = 'Score: ' + String(pts);
        __beep(329.63, 0.1);
        drawDot();
      }
    });

    pts = 0;
    drawDot();
  </script>
</body>
</html>
```

