  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var total;

    document.getElementById("save").addEventListener('click', function () {
      total = (typeof total === 'number' ? total : 0) + (parseFloat(document.getElementById("amt").value) || 0);
      document.getElementById("amt").value = '';
      document.getElementById("saved").textContent = 'Saved: $' + String(total);
      if (total >= 100) {
        document.getElementById("togo").textContent = '🎉 Congrats, you reached your goal!';
        __beep(523.25, 0.4);
      } else {
        document.getElementById("togo").textContent = ['$',100 - total,' to go'].join('');
      }
    });

