<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>날아라 새</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #e0f2fe; color: #1f2937; padding: 24px; }
    canvas { background: #7dd3fc; border: 3px solid #0369a1; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🐤 날아라 새</h1>
  <p>점수: <span id="score">0</span> · 최고: <span id="best">0</span></p>
  <canvas id="game" width="360" height="480"></canvas>
  <p id="msg">스페이스바나 클릭으로 날갯짓!</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const GAP = 140, PIPE_W = 60;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let bird = { x: 80, y: 200, r: 14, vy: 0 };
    let pipes = [];     // { x, top(위 기둥 높이), passed }
    let score = 0;
    let best = 0;
    let frame = 0;
    let running = false;
    let timer = null;

    function startGame() {
      clearInterval(timer);
      bird.y = 200;
      bird.vy = 0;
      pipes = [];
      score = 0;
      frame = 0;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      document.getElementById('score').textContent = 0;
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      if (score > best) best = score;
      document.getElementById('best').textContent = best;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function flap() {
      if (running) bird.vy = -7;
    }

    // 원(새)과 사각형(기둥)의 충돌: 가장 가까운 점까지 거리
    function hitRect(c, x, y, w, h) {
      const nx = Math.max(x, Math.min(c.x, x + w));
      const ny = Math.max(y, Math.min(c.y, y + h));
      return Math.hypot(c.x - nx, c.y - ny) < c.r;
    }

    function tick() {
      if (!running) return;
      frame += 1;
      bird.vy += 0.4;
      bird.y += bird.vy;

      if (frame % 90 === 1) {
        pipes.push({ x: W, top: 60 + Math.random() * (H - GAP - 120), passed: false });
      }
      for (const p of pipes) {
        p.x -= 2.5;
        if (!p.passed && p.x + PIPE_W < bird.x) {
          p.passed = true;
          score += 1;
          document.getElementById('score').textContent = score;
        }
      }
      pipes = pipes.filter(function (p) { return p.x + PIPE_W > 0; });

      // 땅/천장 또는 기둥에 닿으면 끝
      if (bird.y + bird.r > H || bird.y - bird.r < 0) {
        gameOver();
      } else {
        for (const p of pipes) {
          if (hitRect(bird, p.x, 0, PIPE_W, p.top) || hitRect(bird, p.x, p.top + GAP, PIPE_W, H)) {
            gameOver();
            break;
          }
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#16a34a';
      for (const p of pipes) {
        ctx.fillRect(p.x, 0, PIPE_W, p.top);
        ctx.fillRect(p.x, p.top + GAP, PIPE_W, H - p.top - GAP);
      }
      ctx.fillStyle = '#facc15';
      ctx.beginPath();
      ctx.arc(bird.x, bird.y, bird.r, 0, Math.PI * 2);
      ctx.fill();
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      if (e.key === ' ' || e.key === 'ArrowUp') flap();
    });
    canvas.addEventListener('mousedown', flap);
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
```

